RX=[(r'^Movie (\d+)$',r'Vidéo \1'),(r'^(.+) Color( \d)?$',r'\1 coul.\2'),(r'^(.+) Rough( \d)?$',r'\1 croquis\2'),(r'^Color Illustration (\d)$',r'Illustr. couleur \1'),
    (r'^BlackRose and Kite (\d)$',r'BlackRose et Kite \1'),(r'^(%\d) Server$',r'Serveur \1'),(r'^(%\d) Server Breach$',r'Serveur \1 altéré'),(r'^Boss$','Boss'),
    (r'^(Phase \d \w+|Vol\. \d|Cubia( \d)?|Mirage|BlackRose|Balmung|Lios|Data Bug|Virus Core|Mia|Fidhell|Gorre|Destruction|Transformation|Carmina Gadelica|Net Slum|Fort Ouph|Mac Anu|Dun Loireag|Lia Fail|Mr\. Panta|TEMPEST|Cyan|Cat Tank|\.hack|ALTIMIT|Orange Blossom|Red Eye|Blue Moon|Yoshiyuki Sadamoto|Rei Isumi|Liminality|SIGN|Image \d+|Original \d+|BGM \d+)$',None)]
def tr_line(l):
    if l=='' : return l
    if l in LM: return LM[l]
    for rx,rep in RX:
        if re.match(rx,l): return l if rep is None else re.sub(rx,rep,l)
    return None
INPLACE={0x2e240:"Mode vidéo",0x2e250:"Mode musique",0x2e260:"#YFinir le jeu#W",0x2e273:"du #YVol.",0x2e27e:"#W: vidéos",0x2e289:"Revoir les",0x2e297:"vidéos obtenues.",0x2e2a8:"Musique du",0x2e2b8:"bureau",0x2e2c3:"#YFinir le jeu#W.",0x2e2d7:"Indisponible en",0x2e2e9:"mode Parodie.",
 0x2e5e0:"OUI",0x2e5e8:"NON",0x2e5f0:"Ne pas répondre",0x2e600:"Réponse envoyée",0x2e610:"Choisissez une réponse.",0x2e628:"Envoyer ce mail ?",0x2e640:"Nouveau mail !",0x2e660:"Reçu : ",0x2e66a:" mail.",0x2e675:"Aucun mail.",0x2e682:" mails.",
 0x60498:"OUI",0x604a0:"NON",
 0x2edf8:"OUI",0x2ee00:"NON",0x2ee08:"Nv. ",0x2ee10:"Temps",0x2ee18:"Vide",0x2ee20:"Données",0x2ee38:" Mode Parodie"}
def apply(prg,add,add_block,T,report):
    for off,fr in INPLACE.items():
        e=bytes(prg).index(b'\0',off); n=e
        while prg[n]==0: n+=1
        cap=n-off-1; enc=fp.encode(fr); assert len(enc)<=cap,(hex(off),fr,cap)
        prg[off:off+cap]=enc.ljust(cap,b'\0')
    done=skipped=0; left=[]
    for t in strs.targets('desktop.prg',bytes(prg)):
        if not (0x2c378<=t['o']<0x30a60 or 0x5c000<=t['o']<0x60300): continue
        fr=[tr_line(l) for l in t['lines']]
        if any(f is None for f in fr) or fr==t['lines']:
            if any(f is None for f in fr) and len(t['lines'])<6: left.append(t['lines'])
            continue
        a=add_block(fr)
        for s in t['sites']: relocs.repoint(prg,s,a)
        done+=1
    report.append('titres deplaces: %d ; non traduits (hors noms techniques): %d'%(done,sum(1 for l in left if not re.match(r'^(ANM_|TEX_|CMP_|xdd|OBJ_|stfroll|[a-z_0-9]+$|[A-Z_ ]+$)',l[0]))))
    report.extend('   reste: '+' / '.join(l) for l in left if not re.match(r'^(ANM_|TEX_|CMP_|xdd|OBJ_|stfroll|[a-z_0-9@]+$|[A-Z_ ]+$)',l[0]))
EXTRAS=[apply]
